MATCH (t:Tank:PlantItem {unit_id: '291'})
RETURN DISTINCT t.tag AS tag
ORDER BY tag;

MATCH (tk:PlantItem:Tank {tag: 'TK-36802'})-[:line_to]-(v:PlantItem:Valve)<-[:control]-(a:PlantItem {kind: 'actuator'})<-[ :send_signal_to*1.. ]-(c:PlantItem:ProcessControlFunction)
RETURN DISTINCT c.loop_tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'P-16802'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem),
      (head:ProcessInstrumentationFunction {loop_tag: 'BSL-524030'})
WHERE EXISTS { (sensor)-[:send_signal_to*1..]->(head) }
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-20902'}), (b:PlantItem {tag: 'K-20901'}), (gv:PlantItem {tag: 'GV-209001'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> gv AND y <> gv)+ (b)
       } AS reachable

MATCH (:PlantItem {tag: 'F-25101'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessControlFunction {loop_tag: 'TIC-176021'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'H-39301'}), (b:PlantItem {tag: 'E-39301'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'R-39301' AND y.tag <> 'R-39301')+ (b)
}
RETURN a.tag AS tag
