MATCH (a:PlantItem {tag: 'P-15501A'}), (b:PlantItem {tag: 'V-15601'})
RETURN EXISTS {
  MATCH (a)-[:line_to*1..]->(b)
  WHERE NOT EXISTS {
    MATCH (a)-[:line_to*1..]->(blocked:PlantItem {tag: 'CHV-155001'})
